// Bundles Core's SQL migrations so each user's Durable Object can apply them to its own SQLite.
import { readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const names = readdirSync(join(root, "../worker/migrations")).filter((name) => name.endsWith(".sql")).sort();
const lines = [
  "// Generated by scripts/generate-migrations.mjs. Do not edit.",
  ...names.map((name, index) => `import m${index} from "../../worker/migrations/${name}";`),
  "export const CORE_SQL_MIGRATIONS: readonly { name: string; sql: string }[] = [",
  ...names.map((name, index) => `  { name: ${JSON.stringify(name)}, sql: m${index} },`),
  "];",
  "",
];
writeFileSync(join(root, "src/migrations.generated.ts"), lines.join("\n"));
